import { useMemo, useState } from "react";

const scans = [
  { job: "Nightly", when: "24 Nov 02:00", found: 3 },
  { job: "Weekly deep", when: "22 Nov 04:00", found: 0 },
  { job: "Edge quick", when: "21 Nov 11:30", found: 0 },
];

export default function History() {
  const [onlyFindings, setOnly] = useState(false);
  const rows = useMemo(() => scans.filter((s) => !onlyFindings || s.found > 0), [onlyFindings]);
  return (
    <main className="bg-surface-page p-section flex flex-col gap-large min-h-screen">
      <nav aria-label="Breadcrumb"><a href="#jobs" className="text-body text-link underline">Scan jobs</a></nav>
      <h1 className="text-title font-bold text-primary">Scan history</h1>
      <section data-testid="history" className="p-card rounded-card bg-surface-raised border border-default shadow-raised flex flex-col gap-medium">
        <div className="flex justify-between items-center gap-medium bg-surface-raised text-primary rounded-none">
          <h2 className="text-heading font-bold text-primary">Finished scans</h2>
          <button type="button" data-testid="only-findings" aria-pressed={onlyFindings} onClick={() => setOnly(!onlyFindings)} className="h-control px-control rounded-control text-body font-medium bg-inherit text-inherit border border-strong">Only with findings</button>
        </div>
        <table className="w-full">
          <thead>
            <tr><th className="text-caption font-medium text-muted px-medium text-left">Job</th><th className="text-caption font-medium text-muted px-medium text-left">Finished</th><th className="text-caption font-medium text-muted px-medium text-left">Findings</th></tr>
          </thead>
          <tbody>
            {rows.map((s, i) => (
              <tr key={s.job} className={i % 2 ? "h-row border-b border-default bg-surface-sunken" : "h-row border-b border-default bg-transparent"}>
                <td className="text-body px-medium text-primary">{s.job}</td>
                <td className="text-body px-medium text-muted">{s.when}</td>
                <td className={s.found ? "text-body px-medium text-critical" : "text-body px-medium text-ok"}>{s.found ? s.found + " open" : "none"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </main>
  );
}
